use std::fs

fn is_leap(y: int) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn dim(y: int, m: int) -> int {
    if m == 2 {
        if is_leap(y) { 29 } else { 28 }
    } else if m == 4 || m == 6 || m == 9 || m == 11 {
        30
    } else {
        31
    }
}

fn days_from_civil(y0: int, m: int, d: int) -> int {
    let y = if m <= 2 { y0 - 1 } else { y0 }
    let era = y / 400
    let yoe = y - era * 400
    let mp = (m + 9) % 12
    let doy = (153 * mp + 2) / 5 + d - 1
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy
    era * 146097 + doe - 719468
}

// returns days since epoch, or -1000000 if invalid
fn parse_date(s: string) -> int {
    let cs: Vec<char> = s.chars().collect()
    if cs.len() != 10 {
        return -1000000
    }
    let mut i = 0
    let mut vals: Vec<int> = []
    while i < 10 {
        let c = cs[i]
        if i == 4 || i == 7 {
            if c != '-' {
                return -1000000
            }
        } else {
            if c < '0' || c > '9' {
                return -1000000
            }
        }
        i += 1
    }
    let mut y = 0
    let mut m = 0
    let mut d = 0
    let mut j = 0
    while j < 4 {
        y = y * 10 + (cs[j] as int - '0' as int)
        j += 1
    }
    m = (cs[5] as int - '0' as int) * 10 + (cs[6] as int - '0' as int)
    d = (cs[8] as int - '0' as int) * 10 + (cs[9] as int - '0' as int)
    if m < 1 || m > 12 || d < 1 || d > dim(y, m) {
        return -1000000
    }
    days_from_civil(y, m, d)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let names = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if parts.len() != 2 {
            println("invalid")
            continue
        }
        let a = parse_date(parts[0])
        let b = parse_date(parts[1])
        if a == -1000000 || b == -1000000 {
            println("invalid")
            continue
        }
        let lo = if a < b { a } else { b }
        let diff = if a < b { b - a } else { a - b }
        let wd = ((lo + 3) % 7 + 7) % 7
        println("${diff} ${names[wd as usize]}")
    }
}

